import React, { useState } from 'react';
import Header from '../components/Header/Header';
import BookCard from '../components/BookCard/BookCard';
import './CatalogPage.css';

const books = [
    {
      id: 1,
      title: "7 чоловіків Евілін Г'юго",
      imgSrc: "/7-mans-evelin-gugo.jpg",
      description: "Уже літня та замкнута в собі голлівудська ікона кіно..."
    },
    {
      id: 2,
      title: "9 листопада",
      imgSrc: "/9-november.png",
      description: "Як знати, що кохання справжнє? А який він — любовний поцілунок..."
    },
    {
      id: 3,
      title: "Так тобі й треба",
      imgSrc: "/tak-tobi-i-treba.webp",
      description: "«Не хочу рівно, хочу, як у кіно». Від першої закоханості й метеликів..."
    },
    {
      id: 4,
      title: "Жовтолика",
      imgSrc: "/yellowface.webp",
      description: "«Жовтолика» — перший твір Ребекки Кван, у якому вона відходить від епічності,..."
    },
    {
      id: 5,
      title: "Жага",
      imgSrc: "/thirst.webp",
      description: "«Мій світ змінився, щойно я переступила поріг академії. Ніщо не було...."
    },
    {
      id: 6,
      title: "Анатомія: історія кохання",
      imgSrc: "/anatomy.webp",
      description: "«Гейзел — наречена майбутнього віконта, якій кортить стати хірургом більше, ніж...."
    },
    {
      id: 7,
      title: "Король Неверленду",
      imgSrc: "/kingofneverlend.jpg",
      description: "«Протягом двох століть усі жінки роду Дарлінґ зникали у свій 18-й день...."
    }, 
    {
      id: 8,
      title: "Книга ночі",
      imgSrc: "/bookofnight.webp",
      description: "«У світі магії тіней Чарлі Голл — відома злодійка. Десять років вона працювала на...."
    }   
];

function CatalogPage() {
  const [searchTerm, setSearchTerm] = useState(''); // Оголошуємо searchTerm з useState

  // Функція обробки змін в полі пошуку
  const handleSearchChange = (value) => {
    setSearchTerm(value);
  };

  // Фільтрація книг за пошуковим терміном
  const filteredBooks = books.filter((book) =>
    book.title.toLowerCase().includes(searchTerm.toLowerCase().trim())
  );
  
  return (
    <div>
      <Header showSearch={true} onSearchChange={handleSearchChange} />
      
      {/* Грид для рендерингу карток книг */}
      <div className="catalog-page">
        {filteredBooks.map((book) => (
          <BookCard
            key={book.id}
            title={book.title}
            imgSrc={book.imgSrc}
            description={book.description}
          />
        ))}
      </div>
    </div>
  );
}

export default CatalogPage;
